-- Lendwise Finance - Consumer Lending & Credit Risk Analytics
-- Converted from SQLite to MySQL-compatible SQL
-- Observation date: 2026-06-30

CREATE DATABASE IF NOT EXISTS lendwise_finance;
USE lendwise_finance;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `customers`;
CREATE TABLE `customers` (
  `customer_id` VARCHAR(20),
  `age` INT,
  `gender` VARCHAR(255),
  `state` VARCHAR(255),
  `employment_type` VARCHAR(255),
  `monthly_income` DECIMAL(18,2),
  `customer_since` VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `applications`;
CREATE TABLE `applications` (
  `application_id` VARCHAR(20),
  `customer_id` VARCHAR(20),
  `application_date` VARCHAR(255),
  `requested_amount` INT,
  `requested_tenor_months` INT,
  `credit_score` INT,
  `risk_grade` VARCHAR(255),
  `application_status` VARCHAR(255),
  `rejection_reason` VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `credit_bureau`;
CREATE TABLE `credit_bureau` (
  `bureau_id` VARCHAR(20),
  `customer_id` VARCHAR(20),
  `bureau_date` VARCHAR(255),
  `credit_score` INT,
  `existing_loans` INT,
  `existing_balance` DECIMAL(18,2),
  `monthly_debt_obligations` DECIMAL(18,2),
  `previous_defaults` INT,
  `previous_late_payments` INT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `loans`;
CREATE TABLE `loans` (
  `loan_id` VARCHAR(20),
  `application_id` VARCHAR(20),
  `customer_id` VARCHAR(20),
  `disbursement_date` VARCHAR(255),
  `loan_amount` INT,
  `interest_rate` DECIMAL(18,2),
  `fees` DECIMAL(18,2),
  `tenor_months` INT,
  `monthly_payment` DECIMAL(18,2),
  `maturity_date` VARCHAR(255),
  `loan_status` VARCHAR(255),
  `max_dpd` INT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `repayments`;
CREATE TABLE `repayments` (
  `repayment_id` VARCHAR(20),
  `loan_id` VARCHAR(20),
  `installment_number` INT,
  `due_date` VARCHAR(255),
  `payment_date` VARCHAR(255),
  `amount_due` DECIMAL(18,2),
  `principal_due` DECIMAL(18,2),
  `interest_due` DECIMAL(18,2),
  `amount_paid` DECIMAL(18,2),
  `days_past_due` INT,
  `payment_status` VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `collections`;
CREATE TABLE `collections` (
  `collection_id` VARCHAR(20),
  `loan_id` VARCHAR(20),
  `collection_date` VARCHAR(255),
  `collection_channel` VARCHAR(255),
  `dpd_at_contact` INT,
  `amount_collected` DECIMAL(18,2),
  `promise_to_pay` VARCHAR(255),
  `outcome` VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Indexes
CREATE INDEX idx_app_customer ON applications(customer_id);
CREATE INDEX idx_loan_customer ON loans(customer_id);
CREATE INDEX idx_repayment_loan ON repayments(loan_id);
CREATE INDEX idx_collection_loan ON collections(loan_id);

-- Foreign keys
ALTER TABLE applications ADD CONSTRAINT fk_app_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id);
ALTER TABLE credit_bureau ADD CONSTRAINT fk_bureau_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id);
ALTER TABLE loans ADD CONSTRAINT fk_loan_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id);
ALTER TABLE loans ADD CONSTRAINT fk_loan_application FOREIGN KEY (application_id) REFERENCES applications(application_id);
ALTER TABLE repayments ADD CONSTRAINT fk_repayment_loan FOREIGN KEY (loan_id) REFERENCES loans(loan_id);
ALTER TABLE collections ADD CONSTRAINT fk_collection_loan FOREIGN KEY (loan_id) REFERENCES loans(loan_id);

SET FOREIGN_KEY_CHECKS = 1;
